{
  "results": [
    {
      "id": "decision-0001",
      "status": "pass",
      "findings": [
        {
          "dimension": "trick counting and transport",
          "fact": "The initial club plan has feasible entries and correct trick totals.",
          "explanation": "Authorized holdings provide five outside winners: SA, HA, HK, DA and DK. With South's AK864 opposite Q72, cashing CA and CK then leading to CQ produces five club tricks on a 3–2 break, using HA to return. On 4–1, conceding the fourth round establishes the fifth for four club tricks and nine total. A later low heart provides the obvious entry to HK.",
          "quotes": [
            "If clubs divide 3–2, lead to CQ and return to South with HA to cash the remaining clubs for ten tricks.",
            "Against 4–1, cash CQ, return to South with HA, and concede one club to establish the fifth; preserve SA and the remaining diamond honor as recovery entries."
          ]
        }
      ]
    },
    {
      "id": "decision-0002",
      "status": "pass",
      "findings": [
        {
          "dimension": "current play and continuation",
          "fact": "DK wins the current trick and preserves the planned recovery entry.",
          "explanation": "The authorized current trick is DQ–D3–D4, and South holds DA and DK. DK wins, leaving DA available. The retained club route through CA, CK, CQ and HA remains executable.",
          "quotes": [
            "Win with the king, then develop clubs while preserving the diamond ace as a recovery entry."
          ]
        }
      ]
    },
    {
      "id": "decision-0003",
      "status": "pass",
      "findings": [
        {
          "dimension": "club sequencing",
          "fact": "Leading CA begins the retained feasible club route.",
          "explanation": "Authorized history shows South won DK and is on lead with CAK864 opposite CQ72. CA followed by CK permits North to retain CQ for round three; South still has HA for the return from dummy.",
          "quotes": [
            "Start clubs with the ace, keeping dummy’s queen for the third round and checking the break."
          ]
        }
      ]
    },
    {
      "id": "decision-0004",
      "status": "pass",
      "findings": [
        {
          "dimension": "resource preservation",
          "fact": "C2 legally follows suit while preserving the planned club entry.",
          "explanation": "The authorized current trick contains South's CA and West's C3. North holds CQ72, so playing C2 preserves CQ for the third round. South retains CK864 and HA for the stated continuation.",
          "quotes": [
            "Follow low, preserving the queen for the third round of clubs."
          ]
        }
      ]
    },
    {
      "id": "decision-0005",
      "status": "pass",
      "findings": [
        {
          "dimension": "remaining resources and transport",
          "fact": "CK is available and advances the club plan without reusing CA.",
          "explanation": "Authorized history records CA already won; South now holds CK864 and North CQ7. Cashing CK while following with C7 retains CQ for round three, after which North can lead a heart to South's HA.",
          "quotes": [
            "Cash the king to test the club split, preserving dummy’s queen for the next round."
          ]
        }
      ]
    },
    {
      "id": "decision-0006",
      "status": "pass",
      "findings": [
        {
          "dimension": "winner identification and sequencing",
          "fact": "C7 preserves CQ without sacrificing the current winner.",
          "explanation": "Authorized facts show CK and C9 in the current trick, with CA already consumed. North holds CQ7; CK cannot be beaten by any remaining club. Following with C7 leaves CQ for South's next club lead and HA remains the return entry.",
          "quotes": [
            "Preserve the queen to win the third club round; the king already wins this trick."
          ]
        }
      ]
    },
    {
      "id": "decision-0007",
      "status": "pass",
      "findings": [
        {
          "dimension": "establishment and transport",
          "fact": "C4 to CQ draws the sole outstanding club.",
          "explanation": "Authorized history shows defenders played C3, C5, C9 and CT, leaving only CJ outstanding. South holds C864 opposite CQ. Leading C4 to CQ establishes C86, and the retained plan correctly returns through South's available HA.",
          "quotes": [
            "Lead to dummy’s queen, drawing the last opposing club and establishing South’s remaining clubs.",
            "If clubs divide 3–2, lead to CQ and return to South with HA to cash the remaining clubs for ten tricks."
          ]
        }
      ]
    },
    {
      "id": "decision-0008",
      "status": "pass",
      "findings": [
        {
          "dimension": "physical transport",
          "fact": "H4 provides the stated return to South's established clubs.",
          "explanation": "Authorized history shows CQ won the third club round and all five defender clubs have appeared. North is on lead with HK74, while South holds HA63 and C86. H4 to HA reaches the clubs, preserving HK and a later low-heart entry to it.",
          "quotes": [
            "Return to South’s ace to cash the established clubs; dummy’s king remains a later winner."
          ]
        }
      ]
    },
    {
      "id": "decision-0009",
      "status": "pass",
      "findings": [
        {
          "dimension": "entry and trick counting",
          "fact": "HA reaches South and supports the stated ten tricks.",
          "explanation": "Authorized facts show four tricks won, H4–H8 currently played, and South holding HA, C86, DA and SA. HA plus those four South winners and North's reachable HK supplies six more tricks, totaling ten.",
          "quotes": [
            "Win the ace to reach South and cash both established clubs, securing ten tricks with the remaining outside winners."
          ]
        }
      ]
    },
    {
      "id": "decision-0010",
      "status": "pass",
      "findings": [
        {
          "dimension": "feasible remainder",
          "fact": "South can cash both established clubs before the outside winners.",
          "explanation": "Authorized history records HA won and all defender clubs exhausted. South is on lead with C86, DA, SA and H63; North retains HK7. C8 then C6, DA and SA, followed by a low heart to HK, is feasible.",
          "quotes": [
            "Cash the established clubs before taking the remaining outside winners."
          ]
        }
      ]
    },
    {
      "id": "decision-0011",
      "status": "pass",
      "findings": [
        {
          "dimension": "discard and entry preservation",
          "fact": "D5 is a legal discard that preserves the remaining winners.",
          "explanation": "Authorized facts show North void in clubs while South's established C8 is winning. North holds D865 and HK7; discarding D5 preserves HK, while South retains H63 to reach it after cashing C6, DA and SA.",
          "quotes": [
            "Discard a low diamond, preserving the heart king and the major-suit holdings."
          ]
        }
      ]
    },
    {
      "id": "decision-0012",
      "status": "pass",
      "findings": [
        {
          "dimension": "endgame route and counting",
          "fact": "The named remaining winners are available and reachable in the stated order.",
          "explanation": "Authorized facts show six tricks won and South on lead with C6, DA, SA and H63 opposite HK7. C6, DA and SA bring the total to nine; a low heart to HK supplies ten. The omitted heart crossing is obvious and available.",
          "quotes": [
            "Cash the last club, then take the diamond ace, spade ace and heart king for ten tricks."
          ]
        }
      ]
    },
    {
      "id": "decision-0013",
      "status": "pass",
      "findings": [
        {
          "dimension": "discard and continuation",
          "fact": "D6 preserves the feasible outside-winner remainder.",
          "explanation": "Authorized facts show North void in clubs with D86 and HK7 while South's C6 is winning. Discarding D6 leaves HK intact; South retains DA, SA and H63, allowing the remaining winners to be cashed and HK reached.",
          "quotes": [
            "Discard another low diamond, retaining the heart king and major-suit length."
          ]
        }
      ]
    },
    {
      "id": "decision-0014",
      "status": "pass",
      "findings": [
        {
          "dimension": "endgame transport",
          "fact": "DA, SA and a heart crossing provide three more tricks.",
          "explanation": "Authorized facts show seven tricks won, South on lead with DA, SA and H63, and North holding HK7. Cashing DA and SA before leading a low heart to HK is physically feasible and totals ten tricks.",
          "quotes": [
            "Cash the diamond ace before taking the spade ace and crossing to the heart king for ten tricks."
          ]
        }
      ]
    },
    {
      "id": "decision-0015",
      "status": "pass",
      "findings": [
        {
          "dimension": "contract objective and continuation",
          "fact": "SA secures the ninth trick and HK remains reachable for the tenth.",
          "explanation": "Authorized facts show eight tricks won and South on lead with SA94 and H63 opposite HK7. SA guarantees the contract; South can then lead a heart to North's HK for the overtrick.",
          "quotes": [
            "Cash the spade ace to secure the contract, then lead a heart to dummy’s king for the overtrick."
          ]
        }
      ]
    },
    {
      "id": "decision-0016",
      "status": "pass",
      "findings": [
        {
          "dimension": "legal play and feasible remainder",
          "fact": "S2 follows under the winning ace and preserves the final heart winner.",
          "explanation": "Authorized facts show SA–SJ in the current trick and North holding S862 and HK7. S2 legally follows suit without affecting SA's winner. South retains H63, so the unfinished plan's HK winner remains reachable after this ninth trick.",
          "quotes": [
            "Follow low under the ace, retaining dummy’s higher spades.",
            "Keep HK as a separate winner and avoid spending South's entries prematurely."
          ]
        }
      ]
    }
  ]
}
